package com.personal.assistant.module.reminder.service;import com.personal.assistant.common.exception.BusinessException;import com.personal.assistant.module.reminder.dto.ReminderRequest;import com.personal.assistant.module.reminder.entity.Reminder;import com.personal.assistant.module.reminder.entity.NotificationChannel;import com.personal.assistant.module.reminder.mapper.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class)class ReminderServiceTest{@Mock ReminderMapper reminders;@Mock NotificationChannelMapper channels;@Mock NotificationLogMapper logs;@Mock SecretCryptoService crypto;@Mock NotificationService notification;ReminderService service;@BeforeEach void setUp(){service=new ReminderService(reminders,channels,logs,crypto,notification);}@Test void createReminderStartsPending(){service.create(3L,new ReminderRequest("LIFE",1L,null,"缴费","水费",LocalDateTime.now().plusHours(1)));ArgumentCaptor<Reminder> c=ArgumentCaptor.forClass(Reminder.class);verify(reminders).insert(c.capture());assertEquals("PENDING",c.getValue().getStatus());assertEquals(3L,c.getValue().getUserId());}@Test void rejectsUnknownSource(){assertThrows(BusinessException.class,()->service.create(3L,new ReminderRequest("NOPE",null,null,"标题",null,LocalDateTime.now())));}@Test void scanDueRecordsFailureWithoutChannel(){Reminder x=new Reminder();x.setId(1L);x.setUserId(3L);x.setStatus("PENDING");x.setTitle("提醒");when(reminders.selectList(any())).thenReturn(List.of(x));assertEquals(1,service.scanDue());assertEquals("FAILED",x.getStatus());verify(reminders).updateById(x);}
@Test void deletesUnusedOwnedChannel(){NotificationChannel channel=new NotificationChannel();channel.setId(8L);channel.setUserId(3L);when(channels.selectById(8L)).thenReturn(channel);when(reminders.selectCount(any())).thenReturn(0L);service.deleteChannel(3L,8L);verify(channels).deleteById(8L);}
@Test void rejectsDeletingReferencedChannel(){NotificationChannel channel=new NotificationChannel();channel.setId(8L);channel.setUserId(3L);when(channels.selectById(8L)).thenReturn(channel);when(reminders.selectCount(any())).thenReturn(1L);BusinessException error=assertThrows(BusinessException.class,()->service.deleteChannel(3L,8L));assertTrue(error.getMessage().contains("仍被提醒引用"));verify(channels,never()).deleteById(anyLong());}
}
